package edu.pe.cibertec.saibm.libro.infrastructure.in.rest;
import java.util.UUID; import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import edu.pe.cibertec.saibm.libro.application.port.in.BookUseCase;
@RestController @RequestMapping("/api/v1/books") public class BookController { private final BookUseCase books; private final TransitionalWriteAuthorizer auth; public BookController(BookUseCase b,TransitionalWriteAuthorizer a){books=b;auth=a;} @GetMapping public BookUseCase.Page search(@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){if(page<0||size<1||size>100)throw new InvalidRequestException("invalid page");return books.search(new BookUseCase.Search(q.trim(),page,size));} @GetMapping("/{id}") public BookUseCase.View find(@PathVariable UUID id){return books.findActive(id);} @PostMapping @ResponseStatus(HttpStatus.CREATED) public BookUseCase.View create(@Valid @RequestBody Request r,HttpServletRequest h){auth.require(h);return books.create(r.create());} @PutMapping("/{id}") public BookUseCase.View update(@PathVariable UUID id,@Valid @RequestBody Request r,HttpServletRequest h){auth.require(h);return books.update(id,r.update());} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void deactivate(@PathVariable UUID id,HttpServletRequest h){auth.require(h);books.deactivate(id);} public record Request(@NotBlank @Size(max=255)String title,@Size(max=4000)String description,@NotBlank @Size(max=255)String author,@Size(max=300)String imageUrl){BookUseCase.Create create(){return new BookUseCase.Create(title,description,author,imageUrl);} BookUseCase.Update update(){return new BookUseCase.Update(title,description,author,imageUrl);}} }
